import{_ as a,o as s,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/GLM.md","filePath":"manual-en/GLM.md","lastUpdated":1785684581000}'),t={name:"manual-en/GLM.md"};function n(i,e,c,d,p,l){return s(),o("div",null,[...e[0]||(e[0]=[r(`<h3 id="_15-9-glm" tabindex="-1">15.9 GLM <a class="header-anchor" href="#_15-9-glm" aria-label="Permalink to &quot;15.9 GLM&quot;">​</a></h3><pre><code>GLM dependent_vars BY fixed_factors
     [/METHOD = SSTYPE(type)]
     [/DESIGN = interaction_0 [interaction_1 [... interaction_n]]]
     [/INTERCEPT = {INCLUDE|EXCLUDE}]
     [/MISSING = {INCLUDE|EXCLUDE}]
</code></pre><p>The <code>GLM</code> procedure can be used for fixed effects factorial Anova.</p><p>The dependent_vars are the variables to be analysed. You may analyse several variables in the same command in which case they should all appear before the <code>BY</code> keyword.</p><p>The fixed_factors list must be one or more categorical variables. Normally it does not make sense to enter a scalar variable in the fixed_factors and doing so may cause PSPP to do a lot of unnecessary processing.</p><p>The <code>METHOD</code> subcommand is used to change the method for producing the sums of squares. Available values of type are 1, 2 and 3. The default is type 3.</p><p>You may specify a custom design using the <code>DESIGN</code> subcommand. The design comprises a list of interactions where each interaction is a list of variables separated by a ‘*’. For example the command</p><pre><code>GLM subject BY sex age_group race
    /DESIGN = age_group sex group age_group*sex age_group*race
</code></pre><p>specifies the model <em>subject = age_group + sex + race + age_group<em>sex + age_group</em>race</em>. If no <code>DESIGN</code> subcommand is specified, then the default is all possible combinations of the fixed factors. That is to say</p><pre><code>GLM subject BY sex age_group race
</code></pre><p>implies the model <em>subject = age_group + sex + race + age_group<em>sex + age_group</em>race + sex<em>race + age_group</em>sex*race</em>.</p><p>The <code>MISSING</code> subcommand determines the handling of missing variables. If <code>INCLUDE</code> is set then, for the purposes of GLM analysis, only system-missing values are considered to be missing; user-missing values are not regarded as missing. If <code>EXCLUDE</code> is set, which is the default, then user-missing values are considered to be missing as well as system-missing values. A case for which any dependent variable or any factor variable has a missing value is excluded from the analysis.</p>`,12)])])}const h=a(t,[["render",n]]);export{u as __pageData,h as default};
